/**
 * What HeroSplit shows beside the text: a picture, a picture with a floating card, a grid of four pictures with
 * captions, or a picture with two plan cards floating over it.
 */
import { For, type JSX } from "solid-js";
import { Box, Group, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { FigureBlock } from "../components/figure-block";
import { MediaFrame } from "../components/media-frame";
import { OfferMedia } from "../components/offer-media";
import { cn } from "../utils";
import type { HeroContent } from "../blocks/hero-split.types";

export type HeroSplitMediaProps = {
  content: HeroContent;
  alt: string;
  media?: "picture" | "card" | "grid" | "plans";
};

export function HeroSplitMedia({ content, alt, media = "picture" }: HeroSplitMediaProps) {
  return (
    <>
      {((media as string) === "picture") ? (
        <MediaFrame alt={alt} ratio="4/3" />
      ) : null}
      {((media as string) === "card") ? (
        <OfferMedia alt={alt} card={content.card} />
      ) : null}
      {(((media as string) === "grid") && ((content.features?.length ?? 0) > 0)) ? (
        <Box class="grid grid-cols-2 gap-4" data-testid="hero-grid">
          <For each={content.features ?? []}>{(f, iOf) => { const i = iOf(); return (
            <>
              {(i < 4) ? (
                <FigureBlock class="flex flex-col gap-2" testid="hero-tile">
                  <MediaFrame alt={f.title} ratio="1/1" />
                  <Text size="xs" class="text-muted-foreground">
                    {f.title}
                  </Text>
                </FigureBlock>
              ) : null}
            </>
          ); }}</For>
        </Box>
      ) : null}
      {(((media as string) === "plans") && ((content.plans?.length ?? 0) > 0)) ? (
        <Box class="relative" data-testid="hero-media">
          <MediaFrame alt={alt} ratio="4/3" />
          <For each={content.plans ?? []}>{(p, iOf) => { const i = iOf(); return (
            <>
              {(i < 2) ? (
                <Stack
                  gap="2"
                  class={cn(
                    "absolute w-48 rounded bg-card p-4 shadow-lg",
                    ((i === 0) ? "top-8 left-4" : "right-4 bottom-8")
                  )}
                  data-testid="hero-plan"
                >
                  <Text size="sm" weight="semibold">
                    {p.name}
                  </Text>
                  <Group gap="2" align="center">
                    <LucideIcon name="check" size={16} />
                    <Text size="xs" class="text-muted-foreground">
                      {p.tagline}
                    </Text>
                  </Group>
                </Stack>
              ) : null}
            </>
          ); }}</For>
        </Box>
      ) : null}
    </>
  );
}
